async function activation(triggerType, triggerData, reactorToken, item, activationName, api) {
    const { moved } = api.getCumulativeMoveData(reactorToken);

    if (moved < 1) {
        await api.applyEffectsToTokens({
            effectNames: ["invisible"],
            duration: {
                label: "start",
                turns: 1,
            },
            tokens: [reactorToken],
        });
    }
}
